@push('scripts')<script>const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function loadSummary(){const r=await fetch('/enterprise/reports/summary',{headers:{Accept:'application/json'},credentials:'same-origin'});const d=await r.json();const items=[['Erros 7d',d.errors_7d],['Auditoria 30d',d.audit_30d],['E-mails 30d',d.emails_30d],['Falhas e-mail',d.email_failures_30d],['Usuários LDAP',d.directory_users],['Grupos LDAP',d.directory_groups],['WhatsApp 30d',d.whatsapp_30d]];document.getElementById('reportSummary').innerHTML=items.map(([a,b])=>`<div class="v5-card v5-kpi"><small>${esc(a)}</small><strong>${b??0}</strong><span>Indicador operacional</span></div>`).join('')}async function loadOperational(){const days=document.getElementById('reportDays').value;const r=await fetch('/enterprise/reports/operational?days='+days,{headers:{Accept:'application/json'},credentials:'same-origin'});const d=await r.json();const sections=[['Erros por módulo',d.errors_by_module,'modulo'],['Auditoria por ação',d.audit_by_action,'acao'],['E-mails por status',d.emails_by_status,'status']];document.getElementById('operationalReport').innerHTML=sections.map(([title,rows,key])=>`<div class="v5-card"><h3 style="margin-top:0">${title}</h3><table class="v5-table"><tbody>${(rows||[]).map(x=>`<tr><td>${esc(x[key])}</td><td style="text-align:right">${x.total}</td></tr>`).join('')||'<tr><td>Sem dados</td></tr>'}</tbody></table></div>`).join('')}document.getElementById('reportDays').addEventListener('change',loadOperational);loadSummary().catch(()=>{});loadOperational().catch(()=>{});</script>@endpush
